const headers = {
  'accept': 'application/json',
  'user-agent': 'Mozilla/5.0 (Linux; Android 10) AppleWebKit/537.36'
}

async function screenshot(url, opts = {}) {
  const {
    format = 'jpg',
    width = 1280,
    height = 1200,
    scale = 100,
    zoom = 100,
    fullSize = false,
    delay = 3000
  } = opts

  const params = new URLSearchParams()
  params.set('u', encodeURIComponent(url))
  params.set('tkn', '125')
  params.set('d', delay)
  params.set('fs', fullSize ? 1 : 0)
  params.set('w', width)
  params.set('h', height)
  params.set('s', scale)
  params.set('z', zoom)
  params.set('f', String(format).replace(/^\./, ''))
  params.set('rt', 'jweb')

  try {
    const res = await fetch('https://api.pikwy.com/?' + params.toString(), { headers })
    const data = await res.json()
    if (data.code) {
      return { status: false, message: data.mesg }
    }
    return data
  } catch (error) {
    return {
      status: false,
      message: error.message
    }
  }
}

const usage = `Usage: node pikwy.js <url> [format]

Options:
  format  jpg (default) | png | pdf

Example:
  node pikwy.js https://example.com
  node pikwy.js https://example.com pdf
`

async function main() {
  const url = process.argv[2]
  const format = process.argv[3]

  if (!url) {
    console.log(usage)
    return
  }

  const data = await screenshot(url, { format })
  console.log(JSON.stringify(data, null, 2))
}

main()
